
    /* ==========================================================
       EMBEDDED_DATA：内嵌原著文本（全书 100 回·W1316 起由 scripts/sync_search_corpus.py 生成·
       W1317 起 gzip+base64 压缩存储）
       架构：正文压缩存于下方 EMBEDDED_CORPUS_GZ_B64（生成器渲染·禁手改）；运行时
             decodeCorpus() 以 DecompressionStream('gzip') 解压回填 EMBEDDED_DATA.chapters
       文本源：dataset/text-search.json（权威源=source/原文/分回·check_citations.py 语料保真检机器对账）
       ========================================================== */
    const EMBEDDED_CORPUS_GZ_B64 = "";
    const EMBEDDED_DATA = {
        chapters: [],
        characters: ["孙悟空", "美猴王", "石猴", "齐天大圣", "唐僧", "唐三藏", "玄奘", "猪八戒", "猪悟能", "天蓬元帅", "沙僧", "沙悟净", "卷帘大将", "白龙马", "小白龙", "观音", "观世音", "如来", "如来佛祖", "玉帝", "菩提祖师", "阎王", "龙王", "混世魔王", "敖广", "太白金星", "哪吒", "托塔李天王", "李靖", "巨灵神", "二郎神", "太上老君", "王母娘娘", "魏征", "唐太宗", "袁守诚", "惠岸行者", "木吒", "崔珏", "刘伯钦", "镇元大仙", "白骨精", "黄袍怪", "黄风怪", "金角大王", "银角大王", "青牛精", "独角兕大王", "红孩儿", "黑熊精", "铁扇公主", "罗刹女", "牛魔王", "玉面狐狸", "九头虫", "赛太岁", "青毛狮子怪", "黄牙老象", "大鹏金翅鸟", "大鹏雕", "六耳猕猴", "九灵元圣", "黄眉大王", "蝎子精", "百眼魔君", "蜘蛛精", "蜈蚣精", "老鼠精", "玉兔精", "辟寒大王", "辟暑大王", "辟尘大王", "黄狮精", "弥勒佛", "燃灯古佛", "文殊菩萨", "普贤菩萨", "地藏王菩萨", "嫦娥", "殷温娇", "陈光蕊", "女儿国国王", "灭法国王", "寇员外", "金角", "银角", "灵感大王", "通天河老鼋", "凌云渡"],
        artifacts: ["金箍棒", "九齿钉耙", "紧箍咒", "芭蕉扇", "紫金红葫芦", "凤翅紫金冠", "锁子黄金甲", "藕丝步云履", "九环锡杖", "锦澜袈裟", "紧箍儿", "金钢琢", "宣花斧", "羊脂玉净瓶", "幌金绳", "七星剑", "紫金铃", "人种袋", "金铙", "阴阳二气瓶", "三昧真火", "火眼金睛", "筋斗云", "定海神针", "降妖宝杖", "紫金钵盂", "锦襕袈裟", "金箍", "玉兔", "捣药杵", "三尖两刃刀", "哮天犬", "乾坤圈", "混天绫", "风火轮", "降魔杵"]
    };

    /* ==========================================================
       状态
       ========================================================== */
    const state = {
        query: '',
        chapterFilter: 'all'
    };

    const CONTEXT_RADIUS = 50;
    const MAX_RESULTS = 300;

    /* ==========================================================
       工具函数
       ========================================================== */
    function readerHref(num, query) {
        // W1168：结果卡可点开 ⇒ 深链到对应回目页并带检索词做高亮。
        // 约定 `../reader/chNNN.html#q=<词>` 用 hash 而非 query string：file:// 下查询串
        // 可能被当作文件名的一部分解析而打不开，hash 永不参与文件解析（file:// 铁律）。
        // 两层编码缺一不可：encodeURIComponent 保 URL 语义，escapeHtml 保属性边界
        // （本函数结果被拼进 innerHTML 的 href="…"，检索词是用户输入，不转义引号即可越界注入）。
        const pad = String(num).padStart(3, '0');
        return escapeHtml('../reader/ch' + pad + '.html#q=' + encodeURIComponent(query || ''));
    }

    function escapeHtml(s) {
        return String(s).replace(/[&<>"']/g, c => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
        }[c]));
    }
    function normalizeWs(s) {
        return String(s).replace(/\s+/g, ' ').trim();
    }

    /* ==========================================================
       核心检索：返回所有命中位置（回目 + 前后各 50 字上下文）
       ========================================================== */
    function search(query, chapterFilter) {
        const q = (query || '').trim();
        if (!q) return { total: 0, items: [], empty: true, query: '' };

        const chapters = EMBEDDED_DATA.chapters.filter(c =>
            chapterFilter === 'all' || c.num === Number(chapterFilter)
        );

        const items = [];
        let total = 0;
        for (const ch of chapters) {
            const text = ch.text;
            const positions = [];
            let idx = text.indexOf(q);
            while (idx !== -1) {
                positions.push(idx);
                idx = text.indexOf(q, idx + q.length);
            }
            total += positions.length;
            positions.forEach((pos, i) => {
                const start = Math.max(0, pos - CONTEXT_RADIUS);
                const end = Math.min(text.length, pos + q.length + CONTEXT_RADIUS);
                const prefix = normalizeWs(text.slice(start, pos));
                const match = text.slice(pos, pos + q.length);
                const suffix = normalizeWs(text.slice(pos + q.length, end));
                items.push({
                    chapter: ch,
                    position: pos,
                    occIndex: i + 1,
                    occTotal: positions.length,
                    prefix: (start > 0 ? '…' : '') + prefix,
                    match,
                    suffix: suffix + (end < text.length ? '…' : '')
                });
            });
        }
        return { total, items: items.slice(0, MAX_RESULTS), empty: false, query: q, capped: total > MAX_RESULTS };
    }

    /* ==========================================================
       渲染：KPI 概要栏
       ========================================================== */
    function renderKpis() {
        const totalChars = EMBEDDED_DATA.chapters.reduce((s, c) => s + c.text.length, 0);
        const kpis = [
            { label: 'CHAPTERS · 回目', value: EMBEDDED_DATA.chapters.length, desc: '全书 100 回原文' },
            { label: 'CHARS · 字数', value: totalChars.toLocaleString(), desc: '原著正文字符总数' },
            { label: 'CHARACTERS · 人物', value: EMBEDDED_DATA.characters.length, desc: '预设人物快速检索标签' },
            { label: 'ARTIFACTS · 法宝', value: EMBEDDED_DATA.artifacts.length, desc: '预设法宝快速检索标签' }
        ];
        const row = document.getElementById('kpi-row');
        row.innerHTML = kpis.map(k => `
            <div class="kpi-card">
                <div class="label">${k.label}</div>
                <div class="value">${k.value}</div>
                <div class="desc">${k.desc}</div>
            </div>
        `).join('');
    }

    /* ==========================================================
       渲染：快速检索标签
       ========================================================== */
    function renderQuickTags() {
        const charBox = document.getElementById('char-tags');
        charBox.innerHTML = EMBEDDED_DATA.characters.map(name =>
            `<button type="button" class="quick-tag tag-char" data-term="${escapeHtml(name)}" tabindex="0">${escapeHtml(name)}</button>`
        ).join('');
        const artBox = document.getElementById('art-tags');
        artBox.innerHTML = EMBEDDED_DATA.artifacts.map(name =>
            `<button type="button" class="quick-tag tag-art" data-term="${escapeHtml(name)}" tabindex="0">${escapeHtml(name)}</button>`
        ).join('');
    }

    /* ==========================================================
       渲染：结果摘要 + 结果列表
       ========================================================== */
    function renderResults(result) {
        const summary = document.getElementById('results-summary');
        const region = document.getElementById('result-region');

        if (result.empty) {
            summary.style.display = 'none';
            region.innerHTML = `
                <div class="empty-state">
                    <span class="es-icon"><svg class="ico" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6.6C10.6 5.1 8.6 4.6 6 4.6H3.6v12.8c2.6 0 4.6.5 6 1.9 1.4-1.4 3.4-1.9 6-1.9V4.6c-2.6 0-4.6.5-6 2zM12 6.6v12.7" transform="translate(0.2209 -2.6626) scale(1.227)"/></svg></span>
                    在上方输入关键词，或点击人物/法宝标签开始检索。
                    <div class="es-hint">提示：试试「孙悟空」「花果山」「菩提祖师」</div>
                </div>`;
            return;
        }

        if (result.total === 0) {
            summary.style.display = 'block';
            summary.innerHTML = `共找到 <strong>0</strong> 处匹配「<span class="q">${escapeHtml(result.query)}</span>」${state.chapterFilter !== 'all' ? '（当前范围：第 ' + state.chapterFilter + ' 回）' : ''}，未在原文中找到该关键词。`;
            region.innerHTML = `
                <div class="empty-state">
                    <span class="es-icon"><svg class="ico" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true"><path d="M10.6 3.6a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM15.9 15.9l5 5" transform="translate(-0.963 -0.963) scale(1.0582)"/></svg></span>
                    未找到匹配「<strong style="color:var(--accent)">${escapeHtml(result.query)}</strong>」的内容。
                    <div class="es-hint">该词可能出现在尚未收录的回目中，或尝试更换关键词。</div>
                </div>`;
            return;
        }

        const scopeLabel = state.chapterFilter === 'all' ? '全部回目' : '第 ' + state.chapterFilter + ' 回';
        summary.style.display = 'block';
        summary.innerHTML = `共找到 <strong>${result.total}</strong> 处匹配「<span class="q">${escapeHtml(result.query)}</span>」${state.chapterFilter !== 'all' ? '（范围：' + scopeLabel + '）' : ''}${result.capped ? ' · 已显示前 ' + MAX_RESULTS + ' 处' : ''}`;

        region.innerHTML = '<div class="result-list">' + result.items.map(item => `
            <a class="result-card" href="${readerHref(item.chapter.num, result.query)}">
                <div class="rc-head">
                    <span class="rc-chapter">第${item.chapter.num}回</span>
                    <span class="rc-title">${escapeHtml(item.chapter.title)}</span>
                    <span class="rc-count">第 ${item.occIndex}/${item.occTotal} 处</span>
                </div>
                <div class="rc-context">${escapeHtml(item.prefix)}<mark>${escapeHtml(item.match)}</mark>${escapeHtml(item.suffix)}</div>
                <div class="rc-pos">位置：约第 ${item.position} 字</div>
            </a>
        `).join('') + '</div>';
    }

    /* ==========================================================
       交互：执行检索
       ========================================================== */
    let lastReportedQuery = null;

    function reportSearch(result) {
        const q = (result && result.query || '').trim();
        // 一次检索意图 = 一条事件：输入防抖会让同一次查询重复触发，按「查询词是否变化」去重；
        // 空查询不计。值只带命中数，**不回传查询词**（检索词可能含用户私人信息，
        // 而指标只需「查了、有没有查到」——D3/D4 的口径都是命中率而非关键词本身）。
        if (!q || q === lastReportedQuery) { return; }
        lastReportedQuery = q;
        if (window.XYstats) { window.XYstats.count('search_perform', (result.total || 0) + ' hits'); }
    }

    function performSearch() {
        const result = search(state.query, state.chapterFilter);
        renderResults(result);
        reportSearch(result);
    }

    function setQuery(q) {
        state.query = q;
        const input = document.getElementById('search-input');
        input.value = q;
        document.getElementById('search-input-wrap').classList.toggle('has-value', q.trim().length > 0);
        performSearch();
    }

    function setChapterFilter(chap) {
        state.chapterFilter = chap;
        document.querySelectorAll('.chap-btn').forEach(btn => {
            const active = btn.dataset.chap === chap;
            btn.classList.toggle('active', active);
            btn.setAttribute('aria-pressed', active ? 'true' : 'false');
        });
        performSearch();
    }

    /* ==========================================================
       事件绑定
       ========================================================== */
    function bindEvents() {
        const input = document.getElementById('search-input');
        const wrap = document.getElementById('search-input-wrap');
        const clearBtn = document.getElementById('clear-btn');
        const form = document.getElementById('search-form');
        let debounceTimer;

        // W1168 结果打开事件：结果卡是渲染后才出现的，goatcounter 的 bind_events 只在 load 时
        // 绑定一次 ⇒ 声明式属性对动态节点根本不生效（留属性＝「已埋」错觉）。
        // 改挂在**持久容器** #result-region 上做委托（其 innerHTML 每次替换，元素本身不换）。
        // 值刻意留空：href 里含用户检索词，属私人信息，不进统计。
        const region = document.getElementById('result-region');
        if (region) {
            region.addEventListener('click', (e) => {
                const card = e.target && e.target.closest ? e.target.closest('.result-card') : null;
                if (!card || !window.XYstats) { return; }
                window.XYstats.count('search_hit_open', '');
            });
        }

        input.addEventListener('input', () => {
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(() => {
                state.query = input.value;
                wrap.classList.toggle('has-value', input.value.trim().length > 0);
                performSearch();
            }, 150);
        });

        input.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                input.value = '';
                state.query = '';
                wrap.classList.remove('has-value');
                performSearch();
                input.focus();
            }
        });

        form.addEventListener('submit', (e) => {
            e.preventDefault();
            state.query = input.value;
            performSearch();
        });

        clearBtn.addEventListener('click', () => {
            input.value = '';
            state.query = '';
            wrap.classList.remove('has-value');
            performSearch();
            input.focus();
        });
        clearBtn.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                clearBtn.click();
            }
        });

        document.querySelectorAll('.chap-btn').forEach(btn => {
            btn.addEventListener('click', () => setChapterFilter(btn.dataset.chap));
        });

        const onQuickClick = (term) => {
            setQuery(term);
            document.getElementById('results-section').scrollIntoView({ behavior: 'smooth', block: 'start' });
        };
        document.addEventListener('click', (e) => {
            const tag = e.target.closest('.quick-tag');
            if (tag) onQuickClick(tag.dataset.term);
        });
        document.addEventListener('keydown', (e) => {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            const tag = e.target.closest && e.target.closest('.quick-tag');
            if (tag) {
                e.preventDefault();
                onQuickClick(tag.dataset.term);
            }
        });
    }

    /* ==========================================================
       主流程（F6 skeleton：main 包装 + renderAll + 入口 main）
       ========================================================== */
    function renderAll() {
        renderKpis();
        renderQuickTags();
        renderResults(search(state.query, state.chapterFilter));
    }

    /* ==========================================================
       语料解压（W1317：gzip+base64 内嵌 → 运行时回填 chapters）
       ========================================================== */
    function decodeCorpus() {
        // 容量 #4 治理：正文以 gzip(JSON) base64 单串存储（明文块 2.16MB → 约 1.2MB）。
        // DecompressionStream 为浏览器内置、file:// 下零外域可用；不支持时由 main() 的
        // catch 给出明确降级提示（不静默失败）。
        if (typeof DecompressionStream === 'undefined') {
            return Promise.reject(new Error('DecompressionStream unavailable'));
        }
        var bin = atob(EMBEDDED_CORPUS_GZ_B64);
        var bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) { bytes[i] = bin.charCodeAt(i); }
        var stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
        return new Response(stream).text().then(function (json) {
            EMBEDDED_DATA.chapters = JSON.parse(json);
        });
    }

    function showCorpusError() {
        var region = document.getElementById('result-region');
        if (region) {
            region.innerHTML = '<div class="empty-state">离线检索需要浏览器支持 DecompressionStream'
                + '（Chrome/Edge 80+ · Safari 16.4+ · Firefox 113+）。当前浏览器不支持或语料损坏，'
                + '请升级浏览器后刷新本页。</div>';
        }
        window.__xySearchReady = false;
    }

    function main() {
        decodeCorpus().then(function () {
            renderAll();
            bindEvents();
            // 就绪标志：本 app 是 window.load 之后动态注入的（W424 首屏性能优化），
            // 消费方（stat_event_probe / E2E）据此等待而不是靠猜等待时长
            window.__xySearchReady = true;
            const _gt=document.getElementById('gen-time');if(_gt)_gt.textContent =
                '页面生成时间：' + new Date().toISOString().slice(0, 19).replace('T', ' ') + '（本地嵌入）';
        }).catch(function (err) {
            console.warn('[text-search] 语料解压失败:', err);
            showCorpusError();
        });
    }

    main();
    